#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[])
{
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    char *end;
    long long base = strtoll(argv[1], &end, 10);
    if (end != argv[1] + strlen(argv[1])) {
        puts("BAD_INPUT");
        return 0;
    }

    long long exp = strtoll(argv[2], &end, 10);
    if (end != argv[2] + strlen(argv[2])) {
        puts("BAD_INPUT");
        return 0;
    }

    long long mod = strtoll(argv[3], &end, 10);
    if (end != argv[3] + strlen(argv[3])) {
        puts("BAD_INPUT");
        return 0;
    }

    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    base %= mod;
    if (base < 0) base += mod;

    long long result = 1 % mod;
    while (exp > 0) {
        if (exp & 1LL) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1LL;
    }

    printf("result=%lld\n", result);
    return 0;
}
